<?php
declare(strict_types=1);
require_once __DIR__.'/_auth.php';
require_once __DIR__.'/../../includes/work_tracker.php';
$id=(int)($_GET['id']??0);$job=wt_job($pdo,$id);
$q=$pdo->prepare("SELECT id,original_name,mime_type,supplier,receipt_number,purchase_date,gross_total,status,created_at FROM work_receipts WHERE job_id=? ORDER BY COALESCE(purchase_date,DATE(created_at)) DESC,id DESC");
$q->execute([$id]);$receipts=$q->fetchAll(PDO::FETCH_ASSOC);
$mq=$pdo->prepare("SELECT id,description,supplier,receipt_number,purchase_date,COALESCE(actual_cost,cost,0) gross_total,receipt_path FROM work_materials WHERE job_id=? AND receipt_path IS NOT NULL AND receipt_path<>'' ORDER BY COALESCE(purchase_date,DATE(purchased_at)) DESC,id DESC");
$mq->execute([$id]);$materialReceipts=$mq->fetchAll(PDO::FETCH_ASSOC);
$receiptCounts=['processing'=>0,'ready'=>0,'applied'=>0,'failed'=>0];foreach($receipts as $row){$status=(string)$row['status'];$receiptCounts[$status]=($receiptCounts[$status]??0)+1;}
$adminPageTitle='Receipt Images';$adminBreadcrumbs=['Work Tracker'=>'index.php','Job'=>'job.php?id='.$id,'Receipt images'=>''];$adminJob=$job;
