<h2 style="font-size:17px;margin:10px 0 3px"><?=wt_html((string)($r['supplier']?:$r['original_name']))?></h2><div class="receipt-meta"><?=wt_html((string)($r['purchase_date']?:$r['created_at']))?><?php if($r['gross_total']!==null):?> · <?=wt_money((float)$r['gross_total'])?><?php endif;?> · <?=wt_html((string)$r['status'])?></div><a class="btn" href="<?=$url?>" target="_blank">View full receipt</a></article>
<?php endforeach;?>
<?php foreach($materialReceipts as $r):$url='material_receipt.php?job_id='.$id.'&material_id='.(int)$r['id'];$ext=mb_strtolower(pathinfo((string)$r['receipt_path'],PATHINFO_EXTENSION));$isPdf=$ext==='pdf';?>
<article class="receipt-card"><a class="receipt-preview" href="<?=$url?>" target="_blank"><?php if($isPdf):?><iframe src="<?=$url?>#toolbar=0&navpanes=0" title="Receipt PDF preview" loading="lazy"></iframe><?php else:?><img src="<?=$url?>" alt="Receipt for <?=wt_html((string)$r['description'])?>" loading="lazy"><?php endif;?></a><h2 style="font-size:17px;margin:10px 0 3px"><?=wt_html((string)($r['supplier']?:$r['description']))?></h2><div class="receipt-meta"><?=wt_html((string)($r['purchase_date']?:'Date not recorded'))?> · <?=wt_money((float)$r['gross_total'])?> · directly attached</div><a class="btn" href="<?=$url?>" target="_blank">View full receipt</a></article>
